using BARANG.Core.Application.Abstractions.Actors;
using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Security;
using BARANG.Core.Application.Workflow;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.Security;
using BARANG.Core.Domain.Workflow;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace BARANG.Core.Infrastructure.Workflow;
#pragma warning disable CA1725
public sealed class WorkflowAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,ICurrentActor current,ISecurityStore security,IAuditWriter audit,IWorkflowEngineAdapter engine,IWorkflowBusinessCompletionAdapter business,TimeProvider time):IWorkflowAdministration
{
 private Guid Company=>company.RequireCompanyId();private Guid Actor=>Guid.TryParse(current.Actor.UserId,out Guid id)?id:throw new InvalidOperationException("Actor required");private DateTimeOffset Now=>time.GetUtcNow();
 private static readonly WorkflowStage[] Stages=[WorkflowStage.AdministrativeReview,WorkflowStage.FinancialApproval,WorkflowStage.ProductionPlanning,WorkflowStage.DesignPreparation,WorkflowStage.InventoryReservation,WorkflowStage.Printing,WorkflowStage.HeatPress,WorkflowStage.QualityControl,WorkflowStage.Packaging,WorkflowStage.Shipping,WorkflowStage.Delivery,WorkflowStage.Completed];
 public Task<Result<WorkflowInstanceView>>StartAsync(StartWorkflowCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{WorkflowInstance?existing=await db.WorkflowInstances.SingleOrDefaultAsync(x=>x.OrderId==c.OrderId,t);if(existing is not null)return Result.Success(View(existing));Order?o=await db.Orders.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.OrderId,t);if(o is null)return Result.Failure<WorkflowInstanceView>(WorkflowErrors.NotFound);if(o.Status!=OrderStatus.Submitted)return Result.Failure<WorkflowInstanceView>(WorkflowErrors.InvalidTransition);Result<string>started=await engine.StartAsync("ORDER_FULFILLMENT_V1",o.Id,new Dictionary<string,object?>{{"companyId",Company},{"orderId",o.Id}},t);if(started.IsFailure)return Result.Failure<WorkflowInstanceView>(started.Error);WorkflowInstance w=WorkflowInstance.Create(Company,o.Id,started.Value,Now);db.Add(w);HumanTask task=await NewTask(w,WorkflowStage.AdministrativeReview,t);db.Add(task);History(w,task,"InstanceStarted");History(w,task,"TaskCreated");Log("workflow.started",w.Id);return Result.Success(View(w));},ct);
 public Task<Result<WorkflowInstanceView>>GetAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{WorkflowInstance?w=await db.WorkflowInstances.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);return w is null?Result.Failure<WorkflowInstanceView>(WorkflowErrors.NotFound):Result.Success(View(w));},ct);
 public Task<Result<HumanTaskView>>ClaimAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{await LockTask(id,t);HumanTask?task=await db.HumanTasks.SingleOrDefaultAsync(x=>x.Id==id,t);if(task is null)return Result.Failure<HumanTaskView>(WorkflowErrors.NotFound);if(!await Eligible(task.RequiredPermissionCode,t))return Result.Failure<HumanTaskView>(WorkflowErrors.NotEligible);Result r=task.Claim(Actor,version,Now);if(r.IsFailure)return Result.Failure<HumanTaskView>(r.Error);WorkflowInstance w=await db.WorkflowInstances.SingleAsync(x=>x.Id==task.WorkflowInstanceId,t);History(w,task,"TaskClaimed");Log("workflow.task.claimed",task.Id);return Result.Success(View(task));},ct);
 public Task<Result<HumanTaskView>>ReleaseAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{HumanTask?task=await db.HumanTasks.SingleOrDefaultAsync(x=>x.Id==id,t);if(task is null)return Result.Failure<HumanTaskView>(WorkflowErrors.NotFound);Result r=task.Release(Actor,version);if(r.IsFailure)return Result.Failure<HumanTaskView>(r.Error);WorkflowInstance w=await db.WorkflowInstances.SingleAsync(x=>x.Id==task.WorkflowInstanceId,t);History(w,task,"TaskReleased");Log("workflow.task.released",task.Id);return Result.Success(View(task));},ct);
 public async Task<Result<HumanTaskView>>CompleteAsync(Guid id,CompleteWorkflowTaskCommand c,CancellationToken ct)
 {
  Result<CompletionSnapshot> loaded=await tx.ExecuteAsync(async t=>{HumanTask?s=await db.HumanTasks.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);return s is null?Result.Failure<CompletionSnapshot>(WorkflowErrors.NotFound):Result.Success(new CompletionSnapshot(s.Stage,s.OrderId,s.Status,s.ClaimedByUserId,View(s)));},ct);if(loaded.IsFailure)return Result.Failure<HumanTaskView>(loaded.Error);CompletionSnapshot snapshot=loaded.Value;if(snapshot.Status==HumanTaskStatus.Completed)return Result.Success(snapshot.View);if(snapshot.Owner!=Actor)return Result.Failure<HumanTaskView>(WorkflowErrors.NotOwner);
  Result operation=await business.ExecuteAsync(snapshot.Stage,snapshot.OrderId,c.Outcome,c.Reason,ct);if(operation.IsFailure)return Result.Failure<HumanTaskView>(operation.Error);
  return await tx.ExecuteAsync(async t=>{await LockTask(id,t);HumanTask task=await db.HumanTasks.SingleAsync(x=>x.Id==id,t);WorkflowInstance w=await db.WorkflowInstances.SingleAsync(x=>x.Id==task.WorkflowInstanceId,t);Result done=task.Complete(Actor,c.Outcome,c.Reason,c.Version,Now);if(done.IsFailure)return Result.Failure<HumanTaskView>(done.Error);History(w,task,"TaskCompleted",c.Outcome.ToString());WorkflowStage next=Next(task.Stage,c.Outcome);Result signalled=await engine.SignalAsync(w.ProviderInstanceId,$"{task.Stage}:{c.Outcome}",t);if(signalled.IsFailure)return Result.Failure<HumanTaskView>(signalled.Error);Result advanced=w.Advance(next,w.Version,Now);if(advanced.IsFailure)return Result.Failure<HumanTaskView>(advanced.Error);if(next!=WorkflowStage.Completed){HumanTask created=await NewTask(w,next,t);db.Add(created);History(w,created,"TaskCreated");}else History(w,null,"InstanceCompleted");Log("workflow.task.completed",task.Id);return Result.Success(View(task));},ct);
 }
 public Task<Result<WorkflowInstanceView>>SuspendAsync(Guid id,WorkflowReasonCommand c,CancellationToken ct)=>Change(id,c.Version,(w,v)=>w.Suspend(c.Reason,v,Now),"Suspended",x=>engine.SuspendAsync(x,ct),ct);
 public Task<Result<WorkflowInstanceView>>ResumeAsync(Guid id,WorkflowVersionCommand c,CancellationToken ct)=>Change(id,c.Version,(w,v)=>w.Resume(v,Now),"Resumed",x=>engine.ResumeAsync(x,ct),ct);
 public Task<Result<WorkflowInstanceView>>CancelAsync(Guid id,WorkflowReasonCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{WorkflowInstance?w=await db.WorkflowInstances.SingleOrDefaultAsync(x=>x.Id==id,t);if(w is null)return Result.Failure<WorkflowInstanceView>(WorkflowErrors.NotFound);Order?o=await db.Orders.SingleOrDefaultAsync(x=>x.Id==w.OrderId,t);if(o is null)return Result.Failure<WorkflowInstanceView>(WorkflowErrors.NotFound);if(o.Status!=OrderStatus.Cancelled)return Result.Failure<WorkflowInstanceView>(WorkflowErrors.BusinessRejected);Result provider=await engine.CancelAsync(w.ProviderInstanceId,t);if(provider.IsFailure)return Result.Failure<WorkflowInstanceView>(provider.Error);Result r=w.Cancel(c.Reason,c.Version,Now);if(r.IsFailure)return Result.Failure<WorkflowInstanceView>(r.Error);foreach(HumanTask task in await db.HumanTasks.Where(x=>x.WorkflowInstanceId==id&&(x.Status==HumanTaskStatus.Open||x.Status==HumanTaskStatus.Claimed)).ToListAsync(t))task.Cancel();History(w,null,"Cancelled",c.Reason);Log("workflow.cancelled",w.Id);return Result.Success(View(w));},ct);
 public Task<Result<WorkflowPage<HumanTaskView>>>MyTasksAsync(HumanTaskStatus?status,int page,int size,CancellationToken ct)=>tx.ExecuteAsync(t=>Tasks(true,null,status,page,size,t),ct);
 public Task<Result<WorkflowPage<HumanTaskView>>>RoleTasksAsync(WorkflowStage?stage,HumanTaskStatus?status,int page,int size,CancellationToken ct)=>tx.ExecuteAsync(t=>Tasks(false,stage,status,page,size,t),ct);
 public Task<Result<IReadOnlyList<WorkflowHistoryView>>>HistoryAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.WorkflowInstances.AnyAsync(x=>x.Id==id,t))return Result.Failure<IReadOnlyList<WorkflowHistoryView>>(WorkflowErrors.NotFound);var rows=await db.WorkflowHistory.AsNoTracking().Where(x=>x.WorkflowInstanceId==id).OrderBy(x=>x.OccurredAtUtc).ThenBy(x=>x.Id).ToListAsync(t);return Result.Success<IReadOnlyList<WorkflowHistoryView>>(rows.Select(View).ToArray());},ct);
 public Task<Result<WorkflowSlaView>>UpsertSlaAsync(UpsertSlaCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{WorkflowSlaPolicy?p=await db.WorkflowSlaPolicies.SingleOrDefaultAsync(x=>x.Stage==c.Stage,t);if(p is null){Result<WorkflowSlaPolicy>made=WorkflowSlaPolicy.Create(Company,c.Stage,c.DurationMinutes,c.EscalationPermissionCode,Now);if(made.IsFailure)return Result.Failure<WorkflowSlaView>(made.Error);p=made.Value;db.Add(p);}else{Result r=p.Update(c.DurationMinutes,c.IsActive,c.Version);if(r.IsFailure)return Result.Failure<WorkflowSlaView>(r.Error);}Log("workflow.sla.changed",p.Id);return Result.Success(View(p));},ct);
 public Task<Result<int>>EscalateOverdueAsync(CancellationToken ct)=>tx.ExecuteAsync(async t=>{List<HumanTask>tasks=await db.HumanTasks.Where(x=>(x.Status==HumanTaskStatus.Open||x.Status==HumanTaskStatus.Claimed)&&x.DueAtUtc<Now).ToListAsync(t);int count=0;foreach(HumanTask task in tasks){if(await db.WorkflowEscalations.AnyAsync(x=>x.HumanTaskId==task.Id,t))continue;WorkflowSlaPolicy?policy=await db.WorkflowSlaPolicies.AsNoTracking().SingleOrDefaultAsync(x=>x.Stage==task.Stage&&x.IsActive,t);WorkflowEscalation e=WorkflowEscalation.Create(Company,task.Id,policy?.EscalationPermissionCode??SecurityPermissions.WorkflowManage,Now);db.Add(e);WorkflowInstance w=await db.WorkflowInstances.SingleAsync(x=>x.Id==task.WorkflowInstanceId,t);History(w,task,"Escalated");Log("workflow.task.escalated",task.Id);count++;}return Result.Success(count);},ct);
 public Task<Result<IReadOnlyList<ReconciliationView>>>ReconcileAsync(CancellationToken ct)=>tx.ExecuteAsync(async t=>{List<WorkflowInstance>running=await db.WorkflowInstances.Where(x=>x.Status==WorkflowInstanceStatus.Running).ToListAsync(t);var found=new List<WorkflowReconciliationIssue>();foreach(WorkflowInstance w in running){Order?o=await db.Orders.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==w.OrderId,t);string?code=o?.Status==OrderStatus.Cancelled?"ORDER_CANCELLED_WORKFLOW_RUNNING":!await db.HumanTasks.AnyAsync(x=>x.WorkflowInstanceId==w.Id&&(x.Status==HumanTaskStatus.Open||x.Status==HumanTaskStatus.Claimed),t)?"RUNNING_WITHOUT_OPEN_TASK":null;if(code is null||await db.WorkflowReconciliationIssues.AnyAsync(x=>x.WorkflowInstanceId==w.Id&&x.IssueCode==code&&x.Status==ReconciliationStatus.Open,t))continue;var issue=WorkflowReconciliationIssue.Create(Company,w.Id,code,Now);db.Add(issue);found.Add(issue);History(w,null,"ReconciliationIssue",code);Log("workflow.reconciliation.issue",w.Id);}return Result.Success<IReadOnlyList<ReconciliationView>>(found.Select(View).ToArray());},ct);
 private Task<Result<WorkflowInstanceView>>Change(Guid id,long version,Func<WorkflowInstance,long,Result>change,string evt,Func<string,Task<Result>>provider,CancellationToken ct)=>tx.ExecuteAsync(async t=>{WorkflowInstance?w=await db.WorkflowInstances.SingleOrDefaultAsync(x=>x.Id==id,t);if(w is null)return Result.Failure<WorkflowInstanceView>(WorkflowErrors.NotFound);Result pr=await provider(w.ProviderInstanceId);if(pr.IsFailure)return Result.Failure<WorkflowInstanceView>(pr.Error);Result r=change(w,version);if(r.IsFailure)return Result.Failure<WorkflowInstanceView>(r.Error);History(w,null,evt);Log($"workflow.{evt.ToLowerInvariant()}",w.Id);return Result.Success(View(w));},ct);
 private async Task<Result<WorkflowPage<HumanTaskView>>>Tasks(bool mine,WorkflowStage?stage,HumanTaskStatus?status,int page,int size,CancellationToken ct){page=Math.Max(1,page);size=Math.Clamp(size,1,100);IQueryable<HumanTask>q=db.HumanTasks.AsNoTracking();if(mine)q=q.Where(x=>x.ClaimedByUserId==Actor||x.Status==HumanTaskStatus.Open);if(stage is not null)q=q.Where(x=>x.Stage==stage);if(status is not null)q=q.Where(x=>x.Status==status);List<HumanTask>all=await q.OrderByDescending(x=>x.Priority).ThenBy(x=>x.DueAtUtc).ThenBy(x=>x.Id).ToListAsync(ct);var eligible=new List<HumanTask>();foreach(var task in all)if(task.ClaimedByUserId==Actor||await Eligible(task.RequiredPermissionCode,ct))eligible.Add(task);long total=eligible.Count;return Result.Success(new WorkflowPage<HumanTaskView>(eligible.Skip((page-1)*size).Take(size).Select(View).ToArray(),page,size,total));}
 private async Task<HumanTask>NewTask(WorkflowInstance w,WorkflowStage stage,CancellationToken ct){WorkflowSlaPolicy?p=await db.WorkflowSlaPolicies.AsNoTracking().SingleOrDefaultAsync(x=>x.Stage==stage&&x.IsActive,ct);int minutes=p?.DurationMinutes??1440;return HumanTask.Create(Company,w.Id,w.OrderId,stage,TaskType(stage),Required(stage),0,Now,Now.AddMinutes(minutes));}
 private Task<bool>Eligible(string permission,CancellationToken ct)=>security.UserHasPermissionAsync(Actor,Company,permission,Now,ct);
 private async Task LockTask(Guid id,CancellationToken ct){if(db.Database.IsNpgsql())await db.Database.ExecuteSqlInterpolatedAsync($"SELECT id FROM barang.human_tasks WHERE company_id={Company} AND id={id} FOR UPDATE",ct);}
 private void History(WorkflowInstance w,HumanTask?task,string evt,string?summary=null)=>db.WorkflowHistory.Add(WorkflowHistory.Create(Company,w.Id,task?.Id,evt,Now,Actor,summary));private void Log(string action,Guid id)=>audit.Write(new(action,"workflow",id.ToString(),ChangeKind:AuditChangeKind.Modified));
 private static WorkflowStage Next(WorkflowStage s,WorkflowTaskOutcome o){if(s==WorkflowStage.QualityControl&&o==WorkflowTaskOutcome.ReproductionRequested)return WorkflowStage.DesignPreparation;if(o==WorkflowTaskOutcome.Rejected)return WorkflowStage.AdministrativeReview;int i=Array.IndexOf(Stages,s);return i>=0&&i<Stages.Length-1?Stages[i+1]:WorkflowStage.Completed;}
 private static string TaskType(WorkflowStage s)=>s switch{WorkflowStage.AdministrativeReview=>"ADMINISTRATIVE_REVIEW",WorkflowStage.FinancialApproval=>"FINANCIAL_APPROVAL",WorkflowStage.ProductionPlanning=>"PRODUCTION_PLANNING",WorkflowStage.DesignPreparation=>"DESIGN_REVIEW",WorkflowStage.QualityControl=>"QC_REVIEW",WorkflowStage.Packaging=>"PACKAGING_ACTION",WorkflowStage.Shipping=>"SHIPPING_ACTION",WorkflowStage.Delivery=>"DELIVERY_CONFIRMATION",_=>s.ToString().ToUpperInvariant()};
 private static string Required(WorkflowStage s)=>s switch{WorkflowStage.AdministrativeReview=>SecurityPermissions.OrderManage,WorkflowStage.FinancialApproval=>SecurityPermissions.FinanceApprove,WorkflowStage.ProductionPlanning=>SecurityPermissions.ProductionPlan,WorkflowStage.DesignPreparation or WorkflowStage.Printing or WorkflowStage.HeatPress=>SecurityPermissions.ProductionExecute,WorkflowStage.InventoryReservation=>SecurityPermissions.InventoryManage,WorkflowStage.QualityControl=>SecurityPermissions.QCReview,WorkflowStage.Packaging=>SecurityPermissions.PackagingManage,WorkflowStage.Shipping=>SecurityPermissions.ShippingManage,WorkflowStage.Delivery=>SecurityPermissions.DeliveryManage,_=>SecurityPermissions.WorkflowManage};
 private WorkflowInstanceView View(WorkflowInstance w)=>new(w.Id,w.OrderId,w.DefinitionCode,engine.ProviderName,w.ProviderInstanceId,w.CurrentStage,w.Status,w.StartedAtUtc,w.SuspendedAtUtc,w.Version);private static HumanTaskView View(HumanTask x)=>new(x.Id,x.WorkflowInstanceId,x.OrderId,x.Stage,x.TaskTypeCode,x.RequiredPermissionCode,x.Status,x.Priority,x.DueAtUtc,x.ClaimedByUserId,x.Version);private static WorkflowHistoryView View(WorkflowHistory x)=>new(x.Id,x.HumanTaskId,x.EventType,x.OccurredAtUtc,x.ActorUserId,x.Summary);private static WorkflowSlaView View(WorkflowSlaPolicy x)=>new(x.Id,x.Stage,x.DurationMinutes,x.EscalationPermissionCode,x.IsActive,x.Version);private static ReconciliationView View(WorkflowReconciliationIssue x)=>new(x.Id,x.WorkflowInstanceId,x.IssueCode,x.Status,x.DetectedAtUtc);
 private sealed record CompletionSnapshot(WorkflowStage Stage,Guid OrderId,HumanTaskStatus Status,Guid? Owner,HumanTaskView View);
}
#pragma warning restore CA1725
